import type { HorizontalGaugeChartProps, BarProps, LegendProps } from "./chart.types";

import { forwardRef, useMemo, Children, isValidElement, cloneElement, ReactElement } from "react";

import BarChart from "./bar-chart";
import XAxis from "./subcomponents/x-axis";
import YAxis from "./subcomponents/y-axis";

const HorizontalGaugeChart = forwardRef<HTMLDivElement, HorizontalGaugeChartProps>(
  (
    {
      children,
      roundedCorners = true,
      margin = { top: 0, right: 10, bottom: 0, left: 10 },
      styleSlots: styleSlotsProp,
      height: heightProp,
      data,
      ...props
    },
    ref,
  ) => {
    // Calculate smart default margins and height based on child components
    const { defaultHeight } = useMemo(() => {
      const legendChild = Children.toArray(children).find(
        (child) =>
          isValidElement(child) &&
          (child.type as { displayName?: string })?.displayName === "Legend",
      );

      const hasLegend = !!legendChild;

      return {
        // For a gauge with a legend, 120px is a safe bet. Without, 60px is plenty for a 40px bar.
        defaultHeight: hasLegend ? 90 : 60,
      };
    }, [children]);

    const height = heightProp ?? defaultHeight;

    const childrenWithDefaults = Children.map(children, (child) => {
      if (isValidElement(child)) {
        const displayName = (child.type as { displayName?: string })?.displayName;
        if (displayName === "Bar") {
          return cloneElement(child as ReactElement<BarProps>, {
            barSize: (child.props as BarProps).barSize ?? 40,
            showInternalLabel: (child.props as BarProps).showInternalLabel ?? true,
            stackId: (child.props as BarProps).stackId ?? "1",
          });
        }
        if (displayName === "Legend") {
          return cloneElement(child as ReactElement<LegendProps>, {
            layout: (child.props as LegendProps).layout ?? "dashboard",
          });
        }
      }
      return child;
    });

    return (
      <BarChart
        ref={ref}
        data={[data]} // HorizontalGaugeChart expects a single data object, but BarChart expects an array
        height={height}
        layout="vertical"
        margin={margin}
        roundedCorners={roundedCorners}
        styleSlots={{
          surface: { padding: 0 },
          ...styleSlotsProp,
        }}
        type="stacked"
        {...props}
      >
        <XAxis
          hide
          domain={[0, "dataMax"]}
          height={0}
          padding={{ left: 0, right: 0 }}
          type="number"
        />
        <YAxis
          hide
          axisLine={false}
          dataKey="name"
          padding={{ top: 0, bottom: 0 }}
          tickLine={false}
          type="category"
          width={0}
        />
        {childrenWithDefaults}
      </BarChart>
    );
  },
);

HorizontalGaugeChart.displayName = "HorizontalGaugeChart";

export default HorizontalGaugeChart;
